<?php
declare(strict_types=1);
function json_out(array $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function input_json():array{$d=json_decode(file_get_contents('php://input'),true);return is_array($d)?$d:[];}
function csrf_token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function csrf_check():void{$given=$_SERVER['HTTP_X_CSRF_TOKEN']??'';if(!$given||!hash_equals($_SESSION['csrf']??'',(string)$given))json_out(['error'=>'Your session token expired. Refresh the page and try again.'],419);}
function admin_required():void{if(empty($_SESSION['admin']))json_out(['error'=>'Admin sign-in required.'],401);}
function valid_phone(string $phone):bool{return(bool)preg_match('/^(\+?234|0)[789][01]\d{8}$/',preg_replace('/[\s().-]/','',$phone));}
function valid_states():array{return ['Abia','Adamawa','Akwa Ibom','Anambra','Bauchi','Bayelsa','Benue','Borno','Cross River','Delta','Ebonyi','Edo','Ekiti','Enugu','FCT','Gombe','Imo','Jigawa','Kaduna','Kano','Katsina','Kebbi','Kogi','Kwara','Lagos','Nasarawa','Niger','Ogun','Ondo','Osun','Oyo','Plateau','Rivers','Sokoto','Taraba','Yobe','Zamfara'];}
function active_reserved(PDO $pdo,int $productId):int{$s=$pdo->prepare("SELECT COALESCE(SUM(oi.qty),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=? AND o.status='Pending Payment' AND o.created_at>=DATE_SUB(NOW(),INTERVAL 30 MINUTE)");$s->execute([$productId]);return(int)$s->fetchColumn();}
function paystack_call(string $method,string $url,array $payload,string $secret):array{$c=curl_init($url);$opts=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25];if($method!=='GET')$opts[CURLOPT_POSTFIELDS]=json_encode($payload);curl_setopt_array($c,$opts);$raw=curl_exec($c);$status=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);if($raw===false){$err=curl_error($c);curl_close($c);throw new RuntimeException('Gateway request failed: '.$err);}$data=json_decode($raw,true);curl_close($c);if($status<200||$status>=300||!is_array($data)||empty($data['status']))throw new RuntimeException('Gateway verification failed.');return $data;}
function verify_gateway(string $reference,array $cfg):array{if($cfg['gateway']==='paystack'){$r=paystack_call('GET','https://api.paystack.co/transaction/verify/'.rawurlencode($reference),[],$cfg['paystack_secret_key']);$d=$r['data']??[];$ok=($d['status']??'')==='success'&&($d['currency']??'')==='NGN';$amount=(float)($d['amount']??0)/100;}else{$r=paystack_call('GET','https://api.flutterwave.com/v3/transactions/verify_by_reference?tx_ref='.rawurlencode($reference),[],$cfg['flutterwave_secret_key']);$d=$r['data']??[];$ok=($d['status']??'')==='successful'&&($d['currency']??'')==='NGN';$amount=(float)($d['amount']??0);}return ['ok'=>$ok,'amount'=>$amount,'raw'=>$d];}
function fulfill_order(PDO $pdo,array $order,float $paidAmount):bool{if(abs($paidAmount-(float)$order['total'])>0.01)return false;$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$s->execute([$order['id']]);if($s->fetchColumn()!=='Pending Payment'){$pdo->commit();return false;}$s=$pdo->prepare('SELECT product_id,qty FROM order_items WHERE order_id=?');$s->execute([$order['id']]);foreach($s as $item){if($item['product_id']===null)continue;$u=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$u->execute([$item['qty'],$item['product_id'],$item['qty']]);if($u->rowCount()!==1)throw new RuntimeException('Stock is no longer sufficient for order '.$order['reference']);}$u=$pdo->prepare("UPDATE orders SET status='Paid / Pending Delivery',paid_at=NOW() WHERE id=? AND status='Pending Payment'");$u->execute([$order['id']]);$pdo->commit();return $u->rowCount()===1;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function send_mail(PDO $pdo,array $order,array $cfg):void{$s=$pdo->prepare('SELECT product_name,size,qty,unit_price FROM order_items WHERE order_id=?');$s->execute([$order['id']]);$items=[];foreach($s as $i)$items[]=$i['qty'].' x '.$i['product_name'].' - '.($i['size']?:'One size').' (NGN '.number_format((float)$i['unit_price'],2).')';$body="Thank you for shopping with {$cfg['brand']}.\nOrder #{$order['order_number']}\n\n".implode("\n",$items)."\n\nSubtotal: NGN ".number_format((float)$order['subtotal'],2)."\nDelivery: NGN ".number_format((float)$order['delivery_fee'],2)."\nTotal paid: NGN ".number_format((float)$order['total'],2)."\n\nDelivery address: {$order['address']}, {$order['state']}\nReference: {$order['reference']}\n";$from=preg_replace('/[\r\n]/','',$cfg['admin_email']);$headers='From: '.$cfg['brand'].' <'.$from.'>';@mail($order['email'],'Order confirmation #'.$order['order_number'],$body,$headers);@mail($cfg['admin_email'],'New paid order #'.$order['order_number'],$body,$headers);}
function safe_upload_path(?string $p):?string{if(!$p)return null;$name=basename($p);if(!preg_match('/^[a-f0-9]{32}\.(?:webp|jpg)$/',$name))return null;return dirname(__DIR__).'/uploads/'.$name;}
